export const ICON_GROUPS = ["Essentials","Contact & location","Business & money","Shop & delivery","Trades & home","Food & drink","Beauty & health","Travel & leisure","Animals & nature","Learning & tech","Arrows & actions"];

/** An icon as inline SVG ("" if unknown). */
export function iconSvg(name, cls = "eka-ic") {
  const i = ICONS[name];
  return i ? `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${i[2]}</svg>` : "";
}

/** Card/list icons can be an emoji or "i:<name>" from this set. */
export const isIconRef = (v) => typeof v === "string" && v.startsWith("i:") && !!ICONS[v.slice(2)];
